export const TOUR_LABELS = Object.freeze(Object.fromEntries(Object.entries(rows).map(([locale, table]) => [locale, Object.freeze(Object.fromEntries(TOUR_LABEL_KEYS.map(key => [key, table[key]])))])));
const own = id => (Object.hasOwn(TOUR_LABELS, id) ? TOUR_LABELS[id] : undefined);
/** The labels of one language: a locale id or { id }; a variant (pt-BR, de-AT) falls back to its language and everything else to English. */
export function tourLabels(locale) {
  const key = typeof locale === 'string' ? locale : typeof locale?.id === 'string' ? locale.id : 'en';
  return own(key) ?? own(key.replace('-', '_')) ?? own(key.split(/[-_]/u)[0]) ?? TOUR_LABELS.en;
}
